#!/usr/bin/env bash\nset -e\n\n# Mock rationale: test morning greeting\noutput=$(FIXED_HOUR=09 bash ./src/greet.sh)\nif [[ "$output" != "Good morning, brave coder! 🌅" ]]; then\n  echo "Expected morning greeting, got: $output"\n  exit 1\nfi\n\n# Mock rationale: test afternoon greeting\noutput=$(FIXED_HOUR=15 bash ./src/greet.sh)\nif [[ "$output" != "Good afternoon, code explorer! 🌞" ]]; then\n  echo "Expected afternoon greeting, got: $output"\n  exit 1\nfi\n\n# Mock rationale: test evening greeting\noutput=$(FIXED_HOUR=20 bash ./src/greet.sh)\nif [[ "$output" != "Good evening, night owl! 🌙" ]]; then\n  echo "Expected evening greeting, got: $output"\n  exit 1\nfi\n\necho "All greetings correct"\n
